def _carica() -> dict:
    out = {}
    for riga in _R.strip().splitlines():
        p = [x.strip().replace("{F}", FONTE_FRED) for x in riga.split("|")]
        if len(p) == 7:
            out[p[0]] = {"nome": p[1], "gruppo": p[2], "cosa": p[3], "perche": p[4], "lettura": p[5], "fonte": p[6]}
    return out


DATI = _carica()


def scheda(k: str):
    """(cos'è, perché conta, come si legge, fonte) nel formato di glossario_serie, oppure None."""
    d = DATI.get(k)
    return None if d is None else (d["cosa"], d["perche"], d["lettura"], d["fonte"])


def _dai_grafici() -> dict:
    """Le schede dei grafici di confronto (glossario_serie.G), con il nome dell'etichetta del grafico."""
    out = {}
    try:
        from . import confronto, glossario_serie
        for k, label, *_ in confronto.SERIES:
            g = glossario_serie.G.get(k)
            if g and not k.startswith("pm_") and k not in DATI:
                out[k] = {"nome": label, "gruppo": "Indici, volatilità, materie prime e altri dati dei grafici", "cosa": g[0], "perche": g[1], "lettura": g[2], "fonte": g[3] if len(g) > 3 else ""}
    except Exception:  # noqa: BLE001
        pass
    return out


def html() -> str:
    """Elenco ricercabile di tutti i dati spiegati, per gruppo."""
    import html as _h
    e = _h.escape
    gruppi: dict = {}
    for k, d in {**DATI, **_dai_grafici()}.items():
        gruppi.setdefault(d["gruppo"], []).append((k, d))
    out = ["<input id='gdq' type='search' placeholder='Cerca un dato (es. inflazione, credito, liquidità)…' class='glq'><div id='gdlist'>"]
    for g in sorted(gruppi):
        out.append(f"<h4 class='gdg'>{e(g)}</h4>")
        for k, d in sorted(gruppi[g], key=lambda x: x[1]["nome"]):
            out.append(f"<details class='gl gd'><summary>{e(d['nome'])}</summary><p>{e(d['cosa'])}</p><p><b>Perché conta:</b> {e(d['perche'])}</p>"
                       f"<p><b>Come si legge:</b> {e(d['lettura'])}</p><p class='mu'>Fonte: {e(d['fonte'])}</p></details>")
    out.append("</div><script>(function(){var q=document.getElementById('gdq');if(!q)return;q.oninput=function(){var v=q.value.toLowerCase();"
               "document.querySelectorAll('#gdlist .gd').forEach(function(x){x.style.display=x.textContent.toLowerCase().indexOf(v)>=0?'':'none'});"
               "document.querySelectorAll('#gdlist .gdg').forEach(function(h){var n=h.nextElementSibling,s=false;while(n&&n.classList.contains('gd')){if(n.style.display!=='none')s=true;n=n.nextElementSibling}h.style.display=s?'':'none'})}})();</script>")
    return "".join(out)
